        String copy=new CatalogStore(logs).manual(UUID.randomUUID().toString(),"Snapshot",store.get(item.id).title(),"Camera",320,12,"120","","");item.name="Renamed";item.iso=400;store.save(item);check(logs.roll(copy).stock.equals("Test Brand Custom 320")&&logs.roll(copy).iso==320&&logs.roll(oldRoll).stock.equals("Original Stock"),"catalog edits preserve historical roll snapshot");store.archive(item.id,true);check(store.list(false).isEmpty()&&store.list(true).size()==1,"archive");try{store.choose(item.id,"");throw new AssertionError("archived selected");}catch(IllegalArgumentException expected){}store.archive(item.id,false);
